package com.alanmacdougall.mamejibiki.anki

import com.alanmacdougall.mamejibiki.data.Entry
import java.io.File
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Test

/** Checks the Kaishi fields against shared/anki-vectors.json, generated by anki-scripts' own code. */
class KaishiTest {
    private val vectors: List<JsonObject> =
        Json.parseToJsonElement(File(System.getProperty("sharedDir"), "anki-vectors.json").readText()).jsonArray.map { it.jsonObject }

    private fun entry(v: JsonObject) = Entry.decode(v.getValue("entry").toString())
    private fun string(v: JsonObject, key: String) = v.getValue(key).jsonPrimitive.content

    /** The same as anki-scripts, except senses are joined by `<br>` alone, without its newline. */
    @Test fun meaning() {
        for (v in vectors) assertEquals(string(v, "word"), string(v, "meaning").replace("<br>\n", "<br>"), Kaishi.meaning(entry(v)))
    }

    @Test fun grammarNotes() {
        for (v in vectors) assertEquals(string(v, "word"), string(v, "notes"), Kaishi.grammarNotes(entry(v)).joinToString("、"))
    }

    @Test fun pitchHtml() {
        for (v in vectors) {
            val pitch = v.getValue("pitch").takeIf { it != JsonNull }?.jsonObject ?: continue
            assertEquals(string(v, "word"), string(pitch, "html"), Kaishi.pitchHtml(string(pitch, "reading"), string(pitch, "hl")))
        }
    }

    @Test fun note() {
        val v = vectors.first { string(it, "word") == "食べる" }
        val note = Kaishi.note(entry(v), "食べる", "たべる", "LHLL", 184)
        assertEquals(14, note.fields.size)
        assertEquals(listOf("食べる", "たべる"), note.fields.take(2))
        assertEquals("184", note.fields[Kaishi.FREQUENCY])
        assertEquals(setOf(Kaishi.PITCH_ACCENT_TAG, Kaishi.GRAMMAR_TAG), note.tags)
        val noPitch = Kaishi.note(entry(v), "食べる", "たべる", null, null)
        assertEquals("", noPitch.fields[Kaishi.PITCH_ACCENT])
        assertEquals("", noPitch.fields[Kaishi.FREQUENCY])
        assertEquals(setOf(Kaishi.PITCH_ACCENT_UNAVAILABLE_TAG, Kaishi.GRAMMAR_TAG), noPitch.tags)
    }
}
